/**
 * SSR Cache Manager
 *
 * Handles cache key computation, content hashing, temp path management,
 * and cached code validation for the SSR module loader.
 *
 * @module module-system/react-loader/ssr-module-loader/ssr-cache-manager
 */
import * as dntShim from "../../../../_dnt.shims.js";
import { RUNTIME_VERSION } from "../../../utils/version.js";
import { dirname } from "../../../platform/compat/path/index.js";
import { INVALID_ARGUMENT } from "../../../errors/index.js";
import { buildSSRModuleCacheKey } from "../../../cache/keys.js";
import { hashString } from "../../../cache/hash.js";
import { computeConfigHashSync } from "../../../cache/config-hash.js";
import { buildServerExternalPackagesIdentity } from "../../../config/server-external-packages.js";
import { createFileSystem } from "../../../platform/compat/fs.js";
import { rendererLogger } from "../../../utils/index.js";
import { hashCodeHex } from "../../../utils/hash-utils.js";
import { ensureHttpBundlesExist } from "../../../transforms/esm/http-cache.js";
import { parseImports } from "../../../transforms/esm/lexer.js";
import { getHttpBundleCacheDir, getMdxEsmCacheDir } from "../../../utils/cache-dir.js";
import { globalModuleCache, globalTmpDirs } from "./cache/index.js";
import { extractAllFilePathsRecursive, extractAllHttpBundlePathsRecursive, verifiedHttpBundlePaths, } from "./http-bundle-helpers.js";
import { buildTempModulePath, buildTmpDirPath, getTmpDirCacheKey } from "./tmp-paths.js";
import { ensureMdxModuleDependencies } from "../../../transforms/mdx/esm-module-loader/module-fetcher/dependency-recovery.js";
import { ensureCachedVeryfrontEsmPackageScope, ensurePlainCacheDirectory, } from "./esm-package-scope.js";
const logger = rendererLogger.component("ssr-module-loader");
/** Content length threshold: below this, use fast sync hash; above, use async SHA-256 */
const SYNC_HASH_THRESHOLD = 10_000;
/**
 * Manages caching concerns for SSR module loading:
 * - Cache key computation and config hashing
 * - Content hashing (sync for small content, async SHA-256 for large)
 * - Temp file path management
 * - Cached code validation (HTTP bundles, local paths, VF module imports)
 * - Cache entry invalidation
 */
export class SSRCacheManager {
    options;
    fs = createFileSystem();
    cachedConfigHash;
    constructor(options) {
        this.options = options;
    }
    /** Lazily compute config hash once per manager instance. */
    getConfigHash() {
        if (!this.cachedConfigHash) {
            const baseConfigHash = computeConfigHashSync({
                reactVersion: this.options.reactVersion,
                dev: this.options.dev,
                apiBaseUrl: this.options.apiBaseUrl,
                moduleServerOrigin: this.options.moduleServerOrigin,
                dependencyPinningCacheKey: this.options.dependencyPinningCacheKey,
            });
            const serverExternalPackagesIdentity = buildServerExternalPackagesIdentity(this.options.serverExternalPackages);
            const withExternals = serverExternalPackagesIdentity
                ? `${baseConfigHash}:server-externals:${hashString(serverExternalPackagesIdentity)}`
                : baseConfigHash;
            // Preview instruments the transform output with node positions on top of
            // an otherwise identical production compile. `dev` is already in
            // baseConfigHash; the request environment is not, so without this the two
            // would share a cache entry whenever they share a contentSourceId.
            this.cachedConfigHash = this.options.mode === "preview"
                ? `${withExternals}:preview`
                : withExternals;
        }
        return this.cachedConfigHash;
    }
    getCacheKey(filePath, runtimeScope) {
        if (!this.options.contentSourceId) {
            throw INVALID_ARGUMENT.create({
                detail: `Missing contentSourceId for SSR module cache (project: ${this.options.projectId}, file: ${filePath})`,
            });
        }
        const reactVersion = this.options.reactVersion ?? "default";
        const configHash = this.getConfigHash();
        return buildSSRModuleCacheKey(RUNTIME_VERSION, this.options.projectId, `${this.options.contentSourceId}:${reactVersion}:${configHash}:${filePath}${runtimeScope === undefined ? "" : `:react-runtime:${runtimeScope}`}`);
    }
    async hashContentAsync(content) {
        if (content.length < SYNC_HASH_THRESHOLD)
            return hashCodeHex(content);
        try {
            const data = new TextEncoder().encode(content);
            const hashBuffer = await dntShim.crypto.subtle.digest("SHA-256", data);
            const hashArray = Array.from(new Uint8Array(hashBuffer));
            return hashArray
                .slice(0, 8)
                .map((b) => b.toString(16).padStart(2, "0"))
                .join("");
        }
        catch (_) {
            /* expected: WebCrypto may not be available, fall back to sync hash */
            return hashCodeHex(content);
        }
    }
    async getTempPath(filePath, contentHash) {
        const tmpDir = await this.ensureTmpDir();
        return buildTempModulePath(tmpDir, filePath, this.options.projectDir, RUNTIME_VERSION, contentHash);
    }
    isProductionContentSource() {
        const sourceId = this.options.contentSourceId;
        if (!sourceId)
            return !this.options.dev;
        if (sourceId.startsWith("preview-") || sourceId === "preview" || sourceId === "preview-draft") {
            return false;
        }
        if (sourceId.startsWith("release-") ||
            sourceId.startsWith("production-") ||
            sourceId.startsWith("prod-") ||
            sourceId === "production") {
            return true;
        }
        return !this.options.dev;
    }
    async validateCachedCode(code, filePath, source, options) {
        if (options.checkInvalidEsmShPath && /esm\.sh\/_?vf_modules\//.test(code)) {
            logger.warn("[SSR-MODULE-LOADER] Redis cache has invalid esm.sh/_vf_modules URL, re-transforming", {
                file: filePath.slice(-40),
            });
            return false;
        }
        if (await this.hasMissingHttpBundles(code, filePath, source)) {
            return false;
        }
        if (options.checkLocalPaths && await this.hasMissingLocalPaths(code, filePath)) {
            return false;
        }
        if (await this.hasUnresolvedVfModuleImports(code)) {
            logger.warn(source === "memory-cache"
                ? "[SSR-MODULE-LOADER] Memory cache has unresolved _vf_modules imports, invalidating"
                : "[SSR-MODULE-LOADER] Redis cache has unresolved _vf_modules imports, re-transforming", { file: filePath.slice(-40) });
            return false;
        }
        return true;
    }
    async validateMemoryCacheEntry(cachedEntry, contentCacheKey, filePathCacheKey, filePath) {
        const verifyKey = `${cachedEntry.tempPath}:${cachedEntry.contentHash}`;
        if (verifiedHttpBundlePaths.get(verifyKey))
            return globalModuleCache.has(contentCacheKey);
        try {
            const cachedCode = await this.fs.readTextFile(cachedEntry.tempPath);
            const isValid = await this.validateCachedCode(cachedCode, filePath, "memory-cache", {
                checkLocalPaths: true,
                checkInvalidEsmShPath: false,
            });
            if (!isValid) {
                this.invalidateContentAndFileCacheEntries(contentCacheKey, filePathCacheKey, cachedEntry);
                return false;
            }
            verifiedHttpBundlePaths.set(verifyKey, true);
            return globalModuleCache.has(contentCacheKey);
        }
        catch (error) {
            logger.debug("Failed to validate memory cache entry, invalidating", { error });
            this.invalidateContentAndFileCacheEntries(contentCacheKey, filePathCacheKey, cachedEntry);
            return false;
        }
    }
    invalidateFilePathCacheEntry(filePath, cacheEntry) {
        globalModuleCache.delete(this.getCacheKey(filePath));
        if (cacheEntry) {
            this.invalidateMatchingCacheEntries(cacheEntry);
            verifiedHttpBundlePaths.delete(`${cacheEntry.tempPath}:${cacheEntry.contentHash}`);
        }
    }
    invalidateContentAndFileCacheEntries(contentCacheKey, filePathCacheKey, cacheEntry) {
        globalModuleCache.delete(contentCacheKey);
        globalModuleCache.delete(filePathCacheKey);
        if (cacheEntry) {
            verifiedHttpBundlePaths.delete(`${cacheEntry.tempPath}:${cacheEntry.contentHash}`);
        }
    }
    invalidateMatchingCacheEntries(cacheEntry) {
        const keysToDelete = [];
        for (const [key, entry] of globalModuleCache.entries()) {
            if (entry.tempPath === cacheEntry.tempPath &&
                entry.contentHash === cacheEntry.contentHash) {
                keysToDelete.push(key);
            }
        }
        for (const key of keysToDelete) {
            globalModuleCache.delete(key);
        }
    }
    /** Get the filesystem instance for external callers. */
    getFs() {
        return this.fs;
    }
    async hasUnresolvedVfModuleImports(code) {
        const imports = await parseImports(code);
        return imports.some((importSpecifier) => {
            const rawPath = importSpecifier.n;
            if (!rawPath)
                return false;
            const path = rawPath.replace(/^(?:file:\/\/)?\/+/, "");
            return path.startsWith("_vf_modules/");
        });
    }
    async hasMissingHttpBundles(code, filePath, source) {
        const bundlePaths = await extractAllHttpBundlePathsRecursive(code);
        if (bundlePaths.length === 0)
            return false;
        const cacheDir = getHttpBundleCacheDir();
        const failed = await ensureHttpBundlesExist(bundlePaths, cacheDir);
        if (failed.length === 0)
            return false;
        logger.warn("Unrecoverable HTTP bundles, re-transforming", {
            file: filePath.slice(-40),
            failed,
            totalBundles: bundlePaths.length,
            cacheDir,
            source,
        });
        return true;
    }
    async hasMissingLocalPaths(code, filePath) {
        const allPaths = await extractAllFilePathsRecursive(code);
        let firstMissingPathIndex = -1;
        for (let index = 0; index < allPaths.length; index++) {
            const path = allPaths[index];
            try {
                const stat = await this.fs.stat(path);
                if (!stat.isFile) {
                    firstMissingPathIndex = index;
                    break;
                }
            }
            catch (error) {
                logger.debug("Redis cache has invalid local path, re-transforming", {
                    file: filePath.slice(-40),
                    missingPath: path.slice(-60),
                    error,
                });
                firstMissingPathIndex = index;
                break;
            }
        }
        if (firstMissingPathIndex === -1)
            return false;
        if (this.options.projectId &&
            this.options.contentSourceId) {
            const recovered = await ensureMdxModuleDependencies(code, {
                projectId: this.options.projectId,
                contentSourceId: this.options.contentSourceId,
                log: logger,
            });
            if (recovered.recovered.length > 0) {
                logger.debug("Recovered missing local vfmod dependencies for SSR cache entry", {
                    file: filePath.slice(-40),
                    recovered: recovered.recovered.slice(0, 5),
                });
            }
        }
        for (let index = firstMissingPathIndex; index < allPaths.length; index++) {
            const path = allPaths[index];
            try {
                const stat = await this.fs.stat(path);
                if (!stat.isFile)
                    return true;
            }
            catch (_) {
                return true;
            }
        }
        return false;
    }
    async ensureTmpDir() {
        const { projectId, contentSourceId } = this.options;
        if (!projectId) {
            throw INVALID_ARGUMENT.create({
                detail: `Missing projectId for SSR temp directory (projectDir: ${this.options.projectDir})`,
            });
        }
        if (!contentSourceId) {
            throw INVALID_ARGUMENT.create({
                detail: `Missing contentSourceId for SSR temp directory (project: ${projectId})`,
            });
        }
        const baseCacheDir = getMdxEsmCacheDir();
        const sourceKey = contentSourceId;
        const cacheKey = getTmpDirCacheKey(baseCacheDir, projectId, sourceKey, RUNTIME_VERSION);
        const tmpDir = buildTmpDirPath(baseCacheDir, projectId, sourceKey, RUNTIME_VERSION);
        const projectCacheDir = dirname(tmpDir);
        const versionCacheDir = dirname(projectCacheDir);
        // The configured cache location is a same-trust boundary and must not be
        // writable by hostile concurrent actors. Reject pre-existing symlinked
        // segments so generated modules cannot start outside that boundary.
        await this.fs.mkdir(baseCacheDir, { recursive: true });
        for (const directory of [
            baseCacheDir,
            versionCacheDir,
            projectCacheDir,
            tmpDir,
        ]) {
            await ensurePlainCacheDirectory(this.fs, directory);
        }
        await ensureCachedVeryfrontEsmPackageScope(this.fs, tmpDir);
        globalTmpDirs.set(cacheKey, tmpDir);
        return tmpDir;
    }
}
